/*
 Problem: 4070. Minimum Rotations to Dial a Number I
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.5 MB (95.19%)
 Tags: 
*/
class Solution {
public:
    int minRotations(string s) {
        int ans = 0;
        int cur = 0;

        for (const auto& c : s) {
            int nx = c - '0';
            int diff = abs(cur - nx);
            ans += min(diff, 10 - diff);
            cur = nx;
        }

        return ans;
    }
};
